  /** 取壁纸 CSS，非法 id 回落到默认。自定义壁纸（custom_ 前缀）从 config.customWalls 取 url */
  function wallCss(id) {
    if (String(id || '').indexOf('custom_') === 0) {
      const cw = (config.customWalls || []).find((w) => w.id === id);
      return cw ? 'url(' + cw.url + ')' : WALLPAPERS[0].css;
    }
    const w = WALLPAPERS.find((x) => x.id === id) || WALLPAPERS[0];
    return w.css;
  }

  /** 判断壁纸 id 是否为自定义（需要内联 style 而非 CSS 规则） */
