  /**
   * 头像尺寸表。CSS 里的 .tph-ava.szN 规则由这张表生成（见 13-css 的 avaRules）。
   * 以前是手写几条规则，调用方用了没定义的尺寸（38/46/76）时头像会失去宽高、
   * 被 flex 压成一条细线 —— 现在统一走 avaSizeClass 吸附到最近的一档，不会再出这种事。
   */
  const AVA_SIZES = [20, 24, 28, 34, 38, 40, 46, 48, 56, 64, 76, 88];

  /** 把任意请求尺寸吸附到尺寸表里最近的一档 */
  function avaSizeClass(size) {
    const n = Number(size) || 40;
    let best = AVA_SIZES[0];
    let diff = Math.abs(best - n);
    for (let i = 1; i < AVA_SIZES.length; i++) {
      const d = Math.abs(AVA_SIZES[i] - n);
      if (d < diff) { diff = d; best = AVA_SIZES[i]; }
    }
    return best;
  }

