    shell.body.appendChild(wxFnRow('📷', '#3E7BFA', '朋友圈', nMo ? nMo + ' 条动态' : '还没有动态',
      () => { session.wxTab = 'discover'; session.wxSub = 'moments'; session.moCompose = false; renderScreen(); }));
